Description:
There is a problem with Korean search when using utf8mb4_0900_ai_ci collation.
In the case of Hangul, which is separated by digits, it returns results as if they are the same character even though they are clearly different.
If I use utf8mb4_general_ci, which is the default collation before 8.0, I get correct results.
This can be a serious problem, especially when users upgrade from mysql 5.7 to 8.0.

How to repeat:
Run the search test after insert Korean characters using a table with two collations: utf8mb4_0900_ai_ci and utf8mb4_general_ci.

select @@version;
show global variables like '%collation%';
show global variables like '%character_set%';

create database if not exists test default collate=utf8mb4_0900_ai_ci;
create table if not exists test.t_general (id int, name varchar(10)) default collate=utf8mb4_general_ci;
create table if not exists test.t_0900 (id int, name varchar(10)) default collate=utf8mb4_0900_ai_ci;

select table_schema, table_name, table_collation from information_schema.tables where table_schema = 'test' and table_name like 't\_%';
insert into test.t_general values (1, '가나다');
insert into test.t_general values (2, 'ㄱㅏ나다');
insert into test.t_general values (3, 'ㄱㅏㄴㅏㄷㅏ');
insert into test.t_0900 values (1, '가나다');
insert into test.t_0900 values (2, 'ㄱㅏ나다');
insert into test.t_0900 values (3, 'ㄱㅏㄴㅏㄷㅏ');

select * from test.t_general where name = '가나다';
select * from test.t_0900 where name = '가나다';

select * from test.t_general where name = 'ㄱㅏㄴㅏ다';
select * from test.t_0900 where name = 'ㄱㅏㄴㅏ다';

mysql> select @@version;
+-----------+
| @@version |
+-----------+
| 8.0.33    |
+-----------+
1 row in set (0.00 sec)

mysql> show global variables like '%collation%';
+-------------------------------+--------------------+
| Variable_name                 | Value              |
+-------------------------------+--------------------+
| collation_connection          | utf8mb4_0900_ai_ci |
| collation_database            | utf8mb4_0900_ai_ci |
| collation_server              | utf8mb4_0900_ai_ci |
| default_collation_for_utf8mb4 | utf8mb4_0900_ai_ci |
+-------------------------------+--------------------+
4 rows in set (0.00 sec)

mysql> show global variables like '%character_set%';
+--------------------------+--------------------------------+
| Variable_name            | Value                          |
+--------------------------+--------------------------------+
| character_set_client     | utf8mb4                        |
| character_set_connection | utf8mb4                        |
| character_set_database   | utf8mb4                        |
| character_set_filesystem | binary                         |
| character_set_results    | utf8mb4                        |
| character_set_server     | utf8mb4                        |
| character_set_system     | utf8mb3                        |
| character_sets_dir       | /usr/share/mysql-8.0/charsets/ |
+--------------------------+--------------------------------+
8 rows in set (0.01 sec)

mysql> create database if not exists test default collate=utf8mb4_0900_ai_ci;
Query OK, 1 row affected (0.01 sec)

mysql> create table if not exists test.t_general (id int, name varchar(10)) default collate=utf8mb4_general_ci;
Query OK, 0 rows affected (0.01 sec)

mysql> create table if not exists test.t_0900 (id int, name varchar(10)) default collate=utf8mb4_0900_ai_ci;
Query OK, 0 rows affected (0.01 sec)

mysql> select table_schema, table_name, table_collation from information_schema.tables where table_schema = 'test' and table_name like 't\_%';
+--------------+------------+--------------------+
| TABLE_SCHEMA | TABLE_NAME | TABLE_COLLATION    |
+--------------+------------+--------------------+
| test         | t_0900     | utf8mb4_0900_ai_ci |
| test         | t_general  | utf8mb4_general_ci |
+--------------+------------+--------------------+
2 rows in set (0.00 sec)

mysql> insert into test.t_general values (1, '가나다');
Query OK, 1 row affected (0.00 sec)

mysql> insert into test.t_general values (2, 'ㄱㅏ나다');
Query OK, 1 row affected (0.01 sec)

mysql> insert into test.t_general values (3, 'ㄱㅏㄴㅏㄷㅏ');
Query OK, 1 row affected (0.00 sec)

mysql> insert into test.t_0900 values (1, '가나다');
Query OK, 1 row affected (0.00 sec)

mysql> insert into test.t_0900 values (2, 'ㄱㅏ나다');
Query OK, 1 row affected (0.00 sec)

mysql> insert into test.t_0900 values (3, 'ㄱㅏㄴㅏㄷㅏ');
Query OK, 1 row affected (0.00 sec)

mysql>
mysql> select * from test.t_general where name = '가나다';
+------+-----------+
| id   | name      |
+------+-----------+
|    1 | 가나다    |
+------+-----------+
1 row in set (0.00 sec)

mysql> select * from test.t_0900 where name = '가나다';
+------+--------------------+
| id   | name               |
+------+--------------------+
|    1 | 가나다             |
|    2 | ㄱㅏ나다           |
|    3 | ㄱㅏㄴㅏㄷㅏ       |
+------+--------------------+
3 rows in set (0.00 sec)

mysql> select * from test.t_general where name = 'ㄱㅏㄴㅏ다';
Empty set (0.00 sec)

mysql> select * from test.t_0900 where name = 'ㄱㅏㄴㅏ다';
+------+--------------------+
| id   | name               |
+------+--------------------+
|    1 | 가나다             |
|    2 | ㄱㅏ나다           |
|    3 | ㄱㅏㄴㅏㄷㅏ       |
+------+--------------------+
3 rows in set (0.00 sec)
